from pwn import remote
import string

def get_ct_len(msg):
    try:
        r = remote('crypto.chal.csaw.io', 8040, timeout=5)
        r.recvuntil(b'Enter msg:')
        r.sendline(msg.encode())
        data = r.recvline(timeout=5)
        r.close()
        if isinstance(data, bytes):
            out = data.strip()
        else:
            out = data.strip().encode()
        return len(out), out
    except Exception as e:
        return -1, str(e).encode()

def main():
    # Test base case: 64 'A's
    msg = 'A'*64
    clen, cout = get_ct_len(msg)
    print(f'Base input length: {clen} (resp: {cout!r})')
    if clen == -1 or b'error' in cout.lower() or b'invalid' in cout.lower():
        print('Server did NOT accept input of length 64.')
        exit(0)
    # Compression oracle for l[a-z_]
    results = {}
    for X in (string.ascii_lowercase + '_'):
        testmsg = 'l' + X + ('A'*62)
        clen, cout = get_ct_len(testmsg)
        results[X] = (clen, cout)
        print(f'l{X} + 62xA => {clen} (resp: {cout!r})')
    print('RESULTS:')
    for X, (clen, cout) in results.items():
        print(f'l{X}:	{clen}\t{cout!r}')

if __name__ == '__main__':
    main()

import socket
import sys
import hexdump

def try_send(payload):
    HOST = 'crypto.chal.csaw.io'
    PORT = 8040
    s = socket.socket()
    s.settimeout(10)
    s.connect((HOST, PORT))
    s.sendall(payload.encode())
    response = b''
    while True:
        try:
            chunk = s.recv(4096)
            if not chunk:
                break
            response += chunk
        except socket.timeout:
            break
    s.close()
    return response

def find_offset(data, needle):
    return data.find(needle.encode('ascii'))

if __name__ == '__main__':
    inputs = [
        ('A'*32 + '\n', '32xA'),
        ('l' + 'A'*31 + '\n', 'l+31xA')
    ]
    for payload, desc in inputs:
        print(f'--- Sending payload: ({desc})')
        res = try_send(payload)
        print(f'Total received: {len(res)} bytes')
        hexdump.hexdump(res)
        offset = find_offset(res, 'Encrypting service')
        if offset != -1:
            print(f"'Encrypting service' begins at offset: {offset}")
        else:
            print("'Encrypting service' not found in reply")
        print('-'*50)

from pwn import remote
import string

HOST = 'crypto.chal.csaw.io'
PORT = 8040

candidates = string.ascii_lowercase + '_'
results = {}

def probe_candidate(w):
    s = ('layb'+w)*5
    s = s[:128] + '\n'
    r = remote(HOST, PORT)
    r.recvuntil(b'Encrypting service')
    r.send(s.encode())
    data = r.recvuntil(b'Encrypting service', drop=False)
    response = data.decode(errors='ignore')
    # Extract ciphertext between banners
    start = response.find('Encrypting service') + len('Encrypting service')
    end = response.rfind('Encrypting service')
    segment = response[start:end]
    ct = segment.strip()
    return len(ct)

for w in candidates:
    try:
        results[w] = probe_candidate(w)
    except Exception as e:
        results[w] = f'ERROR: {e}'

min_len = None
min_w = None
for w, l in results.items():
    if isinstance(l, int):
        if min_len is None or l < min_len:
            min_len = l
            min_w = w

with open('/home/ctfplayer/ctf_files/flatcrypt_result.txt', 'w') as f:
    for w in candidates:
        f.write(f'{w}: {results[w]}\n')
    f.write(f'\nShortest ciphertext is {min_len} using W={min_w}. Fifth char of PROBLEM_KEY is: {min_w}\n')
